const cad = $input.first().json;

return [{
  json: {
    cad: {
      original_file_name: cad.original_file_name ?? 'drawing.dxf',
      original_format: cad.original_format ?? '',
      normalized_format: cad.normalized_format ?? '',
      converted_from_dwg: cad.converted_from_dwg ?? false,
      selected_layout: cad.selected_layout ?? '',
      warnings: Array.isArray(cad.warnings) ? cad.warnings : [],
      machine_data: cad.machine_data ?? {},
      machine_context: cad.machine_context ?? '',
    },
    page: {
      page_number: 1,
      page_type: 'cad',
      text: cad.machine_context ?? '',
      image_base64: cad.image_base64 ?? '',
    },
  },
}];

const findings = Array.isArray($json.findings) ? $json.findings : [];

const experienceQueries = findings
  .map((finding) => String(finding.experience_query ?? '').trim())
  .filter((query) => query.length > 0);

return {
  json: {
    findings,
    experience_queries: experienceQueries,
  },
};

const prepared = $('Prepare Experience Queries').item.json;
const findings = Array.isArray(prepared.findings) ? prepared.findings : [];
const results = Array.isArray($json.results) ? $json.results : [];

const experienceByFinding = {};

for (let index = 0; index < findings.length; index += 1) {
  const finding = findings[index];
  const result = results[index] ?? {};

  experienceByFinding[finding.finding_id] = Array.isArray(result.sources)
    ? result.sources
    : [];
}

return {
  json: {
    findings,
    experience_by_finding: experienceByFinding,
  },
};

const prepared = $('Prepare CAD Context').item.json;
const understanding = $('Understand CAD').item.json;
const queries = $('Build Normative Queries').item.json;
const normative = $('Search Normative').item.json;
const userPackages = $('Search User Packages').item.json;
const check = $('Check Norms').item.json;
const finalization = $json;
const findings = Array.isArray(finalization.findings)
  ? finalization.findings
  : [];

return {
  json: {
    status: 'completed',
    source_mode: 'cad_only',
    file_name: prepared.cad.original_file_name,
    analyzed_pages: 1,
    findings_count: findings.length,
    summary:
      findings.length > 0
        ? `Найдено замечаний: ${findings.length}.`
        : 'Замечания по CAD-чертежу не найдены.',
    findings,
    cad: prepared.cad,
    page: {
      page_number: 1,
      heuristic_page_type: 'cad',
      facts: understanding.facts ?? {},
      understanding_metrics: understanding.metrics ?? {},
      normative_queries: queries.queries ?? [],
      normative_sources: normative.sources ?? [],
      user_package_sources: userPackages.sources ?? [],
      normative_embedding_model: normative.embedding_model ?? '',
      user_package_embedding_model: userPackages.embedding_model ?? '',
      normative_check: {
        summary: check.summary ?? '',
        findings: check.findings ?? [],
        metrics: check.metrics ?? {},
      },
      finalization: {
        summary: finalization.summary ?? '',
        metrics: finalization.metrics ?? {},
      },
    },
    pipeline: [
      'cad_extract',
      'page_understanding',
      'normative_queries',
      'normative_search',
      'user_package_search',
      'normative_check',
      'experience_search',
      'finalization',
    ],
    limitations: [
      'Пользовательские пакеты являются контекстом проекта, а не нормативным доказательством.',
      'В CAD-only workflow не используется контекст пояснительной записки.',
    ],
  },
};
